function nuitsAvantNoel(jour, mois, annee) {
  const bissextile = (annee % 4 === 0 && annee % 100 !== 0) || annee % 400 === 0;
  const longueurs = [31, bissextile ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  let rang = jour;
  for (let m = 0; m < mois - 1; m++) {
    rang += longueurs[m];
  }
  const noel = bissextile ? 360 : 359;
  return Math.max(0, noel - rang);
}

