function jourDeLaSemaine(jour, mois, annee) {
  const noms = ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"];
  const bissextile = (a) => (a % 4 === 0 && a % 100 !== 0) || a % 400 === 0;
  const longueurs = [31, bissextile(annee) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  // nombre de jours écoulés depuis le 1er janvier 2000 (négatif avant)
  let ecart = jour - 1;
  for (let m = 0; m < mois - 1; m++) {
    ecart += longueurs[m];
  }
  if (annee >= 2000) {
    for (let a = 2000; a < annee; a++) {
      ecart += bissextile(a) ? 366 : 365;
    }
  } else {
    for (let a = annee; a < 2000; a++) {
      ecart -= bissextile(a) ? 366 : 365;
    }
  }
  // le 1er janvier 2000 est le rang 5 de la liste (samedi)
  return noms[(((5 + ecart) % 7) + 7) % 7];
}

