def jour_de_la_semaine(jour, mois, annee):
    noms = ["lundi", "mardi", "mercredi", "jeudi", "vendredi", "samedi", "dimanche"]

    def bissextile(a):
        return (a % 4 == 0 and a % 100 != 0) or a % 400 == 0

    longueurs = [31, 29 if bissextile(annee) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    # nombre de jours écoulés depuis le 1er janvier 2000 (négatif avant)
    ecart = jour - 1
    for m in range(mois - 1):
        ecart += longueurs[m]
    if annee >= 2000:
        for a in range(2000, annee):
            ecart += 366 if bissextile(a) else 365
    else:
        for a in range(annee, 2000):
            ecart -= 366 if bissextile(a) else 365
    # le 1er janvier 2000 est le rang 5 de la liste (samedi)
    return noms[((5 + ecart) % 7 + 7) % 7]

